$ErrorActionPreference = "Stop"\n\nWrite-Host "Telly Shine - local SQLite setup" -ForegroundColor Cyan\n\nif (-not (Get-Command node -ErrorAction SilentlyContinue)) { throw "Node.js 18+ is required. Install Node.js and run this script again." }\nif (-not (Get-Command npm -ErrorAction SilentlyContinue)) { throw "npm is not available in PATH." }\n\nif (-not (Test-Path ".env")) {\n  if (Test-Path ".env.local.example") { Copy-Item ".env.local.example" ".env" } else {\n    @\"\nDATABASE_URL=\"file:./dev.db\"\nAUTH_SECRET=\"tellyshine-local-secret-2026\"\nNEXT_PUBLIC_SITE_URL=\"http://localhost:3000\"\n\"@ | Set-Content ".env"\n  }\n}\n\nif (-not (Test-Path "node_modules")) {\n  Write-Host "Installing npm dependencies..." -ForegroundColor Cyan\n  npm install\n}\n\nnpx prisma generate\nnpx prisma db push\nnpm run db:seed\nnpm run db:reset-admin\n\nWrite-Host ""\nWrite-Host "SQLite database is ready." -ForegroundColor Green\nWrite-Host "Admin: http://localhost:3000/admin/login" -ForegroundColor Green\nWrite-Host "Email: admin@tellyshine.com" -ForegroundColor Green\nWrite-Host "Password: TellyShine@123" -ForegroundColor Green\nWrite-Host "Start the website with: npm run dev" -ForegroundColor Green\n